function [ok,detail]=validate_vlsi2024_artifacts(root,varargin)
%VALIDATE_VLSI2024_ARTIFACTS Reopen and validate the paper evidence contract.
ok=false; detail='';
requireSummary=~(nargin>1&&strcmpi(char(varargin{1}),'ignore_summary'));
try
    required={"config.json","assumptions.md","baseline_metrics.csv","ffe_3_vs_6.csv","channel_il.csv",...
        "channel_response.csv","channel_il_at_28GHz.csv","loss_sweep_metrics.csv","static_regression_summary.csv","ac_ctle.csv",...
        "ctle_adaptation_trace.csv","cdr_lock_trace.csv","pi_code_trace.csv","residual_phase_histogram.csv",...
        "jitter_tolerance.csv","ac_solution.csv","checker_alignment.csv","adaptation_state_trace.csv","paper_comparison.csv","paper_comparison.md",...
        "regression_summary.csv","baseline_probes.mat","plots/cdr_residual_phase.png",...
        "legacy_t1_t9/summary.csv","legacy_t1_t9/junit.xml","legacy_t1_t9/manifest.json","legacy_t1_t9/probes.json",...
        "legacy_t1_t9/T1_eye_metrics.csv","legacy_t1_t9/T3_bathtub.csv","legacy_t1_t9/T6_patterns.csv",...
        "legacy_t1_t9/T7_modulation.csv","legacy_t1_t9/T9_loopback.csv","legacy_t1_t9/T3_bathtub.png"};
    for k=1:numel(required), assert(isfile(fullfile(root,required{k})),'Missing artifact: %s',required{k}); end
    t1Names={"T1_eye_NRZ_28G_0dB.png","T1_eye_NRZ_28G_4dB.png","T1_eye_NRZ_28G_8dB.png","T1_eye_NRZ_28G_10dB.png",...
        "T1_eye_NRZ_56G_0dB.png","T1_eye_NRZ_56G_4dB.png","T1_eye_NRZ_56G_8dB.png","T1_eye_NRZ_56G_10dB.png",...
        "T1_eye_PAM4_28G_0dB.png","T1_eye_PAM4_28G_4dB.png","T1_eye_PAM4_28G_8dB.png","T1_eye_PAM4_28G_10dB.png",...
        "T1_eye_PAM4_56G_0dB.png","T1_eye_PAM4_56G_4dB.png","T1_eye_PAM4_56G_8dB.png","T1_eye_PAM4_56G_10dB.png"};
    for k=1:numel(t1Names), info=imfinfo(fullfile(root,'legacy_t1_t9',t1Names{k})); assert(info.Width>0&&info.Height>0,'invalid T1 PNG'); end
    t3Png=imfinfo(fullfile(root,'legacy_t1_t9','T3_bathtub.png')); assert(t3Png.Width>0&&t3Png.Height>0,'invalid T3 PNG');
    cfg=jsondecode(fileread(fullfile(root,'config.json')));
    assert(isfield(cfg,'link')&&isfield(cfg.link,'nBits')&&cfg.link.nBits>0,'config link.nBits missing');
    assert(isfield(cfg.link,'pam4Mapping')&&strcmp(cfg.link.pam4Mapping,'gray_00_01_11_10')&&...
        isequal(cfg.link.pam4Levels(:),[-3;-1;1;3])&&isequal(cfg.link.pam4Thresholds(:),[-2;0;2]),'PAM4 contract metadata missing');
    assert(isfield(cfg,'txPma')&&isfield(cfg.txPma,'lane')&&cfg.txPma.lane.logicalOuterLevel==3,'logical outer level missing');
    assert(isfield(cfg.txPma.lane,'targetSwing')&&isfield(cfg.rxPma.lane,'acSelectedMode'), 'physical swing/AC metadata missing');
    assert(isfield(cfg,'model')&&isfield(cfg.model,'useReferenceAlign')&&~cfg.model.useReferenceAlign,...
        'formal config must disable reference alignment');
    assert(isfield(cfg.model,'trainingMode')&&strcmp(cfg.model.trainingMode,'decision_directed'),...
        'formal training mode is not decision_directed');
    assert(isfield(cfg.model,'cdrOptions')&&cfg.model.cdrOptions.nCodes==64,'PI code count missing');
    metrics=readtable(fullfile(root,'baseline_metrics.csv')); checkBer(metrics,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},...
        {'mode','rate_context_Gbps','line_rate_Gbps','lane_context','sample_bits','pam4_mapping','logical_outer_level','physical_target_swing',...
        'four_levels_valid','tail_lock','lock_loss_count','checker_lag_ui','leveling_scale','leveling_fit_residual','leveling_finite_fraction'});
    assert(ismember('lane',metrics.Properties.VariableNames)&&all(metrics.lane>=1),'baseline lane schema');
    assert(all(string(metrics.pam4_mapping)=="gray_00_01_11_10")&&all(metrics.logical_outer_level==3)&&all(metrics.four_levels_valid)&&...
        all(metrics.tail_lock)&&all(metrics.empirical_BER<0.25)&&all(isfinite(metrics.leveling_fit_residual))&&...
        all(metrics.leveling_fit_residual<=0.15+1e-12)&&all(metrics.leveling_finite_fraction==1),'baseline PAM4/BER gates failed');
    lock=readtable(fullfile(root,'cdr_lock_trace.csv')); requireVars(lock,{'sample','locked','transition','pi_raw_code',...
        'pi_wrapped_code','pi_applied_code','pi_mismatch_LSB','pi_wrap_count','data_phase_UI','edge_phase_UI','residual_phase_UI',...
        'currently_locked','ever_locked','lock_loss_count','cycle_slip','pi_wrap_event','pi_unwrapped_code','pi_sample_time','four_level_valid','four_occupancy_min','logical_eye_margin',...
        'lock_start','lock_loss','first_valid_lock_ui','measurement_start_ui','continuous_tail_lock','tail_lock_losses','tail_cycle_slips','tail_level_valid'});
    assert(height(lock)>0&&any(lock.currently_locked),'formal CDR never locked'); assert(all(isfinite(lock.residual_phase_UI)),'nonfinite residual trace');
    assert(any(lock.ever_locked)&&all(lock.pi_sample_time>=1)&&all(lock.cycle_slip==0),'CDR lock/PI metadata invalid');
    assert(all(lock.continuous_tail_lock)&&all(lock.tail_lock_losses==0)&&all(lock.tail_cycle_slips==0)&&all(lock.tail_level_valid),...
        'continuous post-lock tail invariant failed');
    pi=readtable(fullfile(root,'pi_code_trace.csv')); requireVars(pi,{'sample','pi_raw_code','pi_wrapped_code','pi_applied_code',...
        'pi_mismatch_LSB','pi_wrap_count','pi_wrap_event','pi_unwrapped_code','pi_sample_time','pi_trace_stride'}); assert(all(pi.pi_trace_stride>=1)&&all(pi.cycle_slip==0),'invalid PI stride/cycle slip');
    hist=readtable(fullfile(root,'residual_phase_histogram.csv')); requireVars(hist,{'count','sample_count'});
    assert(all(hist.count>=0)&&all(hist.sample_count==hist.sample_count(1))&&sum(hist.count)==hist.sample_count(1),...
        'residual histogram does not cover every sample');
    il=readtable(fullfile(root,'channel_il.csv')); requireVars(il,{'requested_loss_dB','measured_loss_dB','measured_bits','error_dB','tolerance_dB'});
    assert(all(il.measured_bits>0)&&all(isfinite(il.measured_loss_dB))&&...
        all(abs((il.measured_loss_dB-il.requested_loss_dB)-il.error_dB)<=1e-12)&&all(abs(il.error_dB)<=il.tolerance_dB),...
        'channel IL schema/value invariant failed');
    il28=readtable(fullfile(root,'channel_il_at_28GHz.csv')); requireVars(il28,{'requested_loss_dB','measured_loss_dB','error_dB','tolerance_dB'});
    assert(all(abs((il28.measured_loss_dB-il28.requested_loss_dB)-il28.error_dB)<=1e-12)&&all(abs(il28.error_dB)<=il28.tolerance_dB),...
        'channel IL at 28 GHz invariant failed');
    response=readtable(fullfile(root,'channel_response.csv')); requireVars(response,{'frequency_GHz','baud_GBd','requested_loss_dB','measured_loss_dB','error_dB','tolerance_dB','mode','unmodeledCrosstalk'});
    assert(all(response.frequency_GHz>0)&&all(response.baud_GBd>0)&&...
        all(abs((response.measured_loss_dB-response.requested_loss_dB)-response.error_dB)<=1e-12)&&...
        all(abs(response.error_dB)<=response.tolerance_dB),...
        'channel response schema/value invariant failed');
    loss=readtable(fullfile(root,'loss_sweep_metrics.csv')); checkBer(loss,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},...
        {'mode','rate_context_Gbps','line_rate_Gbps','lane_context','sample_bits','lossAtRef_dB'});
    ffe=readtable(fullfile(root,'ffe_3_vs_6.csv')); checkBer(ffe,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},...
        {'mode','rate_context_Gbps','line_rate_Gbps','lane_context','sample_bits','variant','tap_count','coefficients'});
    ac=readtable(fullfile(root,'ac_ctle.csv')); checkBer(ac,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},...
        {'mode','rate_context_Gbps','line_rate_Gbps','lane_context','sample_bits','ac_enabled','ctle_requested_dB','ctle_applied_dB'});
    acSolution=readtable(fullfile(root,'ac_solution.csv')); requireVars(acSolution,{'mode','cornerRelNyq','four_levels_valid','tail_lock','measurement_valid','eye_margin','errors','measured_bits','aggregate_BER','ber_upper_95','checker_lag_ui','leveling_scale','first_valid_lock_ui','measurement_start_ui','continuous_tail_lock','tail_lock_losses','tail_cycle_slips','tail_level_valid','model_selected_assumption'});
    assert(height(acSolution)==15&&isequal(sort(unique(acSolution.cornerRelNyq))',[1e-4 3e-4 1e-3 3e-3 1e-2])&&...
        isequal(sort(unique(string(acSolution.mode))),sort(["pre-only";"post-only";"pre+post"]))&&...
        any(acSolution.four_levels_valid&acSolution.tail_lock&acSolution.eye_margin>0),'AC solution matrix invalid');
    measured=logical(acSolution.measurement_valid); assert(all(acSolution.measured_bits(measured)>0&isfinite(acSolution.measured_bits(measured)))&&...
        all(acSolution.errors(measured)>=0&acSolution.errors(measured)<=acSolution.measured_bits(measured))&&...
        all(isfinite(acSolution.aggregate_BER(measured))&acSolution.aggregate_BER(measured)>=0&acSolution.aggregate_BER(measured)<=1)&&...
        all(abs(acSolution.aggregate_BER(measured)-acSolution.errors(measured)./acSolution.measured_bits(measured))<=1e-12)&&...
        all(isfinite(acSolution.ber_upper_95(measured))&acSolution.ber_upper_95(measured)>=acSolution.aggregate_BER(measured)-1e-12&acSolution.ber_upper_95(measured)<=1)&&...
        all(isfinite(acSolution.leveling_scale(measured))&acSolution.leveling_scale(measured)>0)&&all(isfinite(acSolution.eye_margin(measured))&acSolution.eye_margin(measured)>0)&&...
        all(acSolution.first_valid_lock_ui(measured)>0)&all(acSolution.measurement_start_ui(measured)>=acSolution.first_valid_lock_ui(measured))&&...
        all(acSolution.continuous_tail_lock(measured))&&all(acSolution.tail_lock_losses(measured)==0)&&all(acSolution.tail_cycle_slips(measured)==0)&&all(acSolution.tail_level_valid(measured)),...
        'AC solution BER/UCB/leveling/eye invariant failed');
    checker=readtable(fullfile(root,'checker_alignment.csv')); requireVars(checker,{'lane','checker_lag_ui','sync_bits','measurement_bits','alignment_valid','framing_valid','errors','measured_bits','empirical_BER','ber_upper_95',...
        'measurement_start_ui','first_valid_lock_ui','continuous_tail_lock','tail_lock_losses','tail_cycle_slips','tail_level_valid'});
    checkBer(checker,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},{'mode','measurement_start_ui'});
    assert(all(checker.alignment_valid)&&all(checker.framing_valid)&&all(checker.continuous_tail_lock)&&all(checker.tail_lock_losses==0)&&...
        all(checker.tail_cycle_slips==0)&&all(checker.tail_level_valid)&&all(checker.measurement_start_ui>=checker.first_valid_lock_ui),...
        'checker alignment/tail invalid');
    jitter=readtable(fullfile(root,'jitter_tolerance.csv')); checkBer(jitter,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},...
        {'mode','rate_context_Gbps','line_rate_Gbps','lane_context','sample_bits','jitter_UI_rms','sweep_context'});
    static=readtable(fullfile(root,'static_regression_summary.csv')); checkBer(static,{'errors','measured_bits','empirical_BER','seed','ber_upper_95'},...
        {'mode','rate_context_Gbps','line_rate_Gbps','lane_context','sample_bits','variant'});
    ctle=readtable(fullfile(root,'ctle_adaptation_trace.csv')); requireVars(ctle,{'objective','disturbed_objective','recovered_objective','control_changed','residual_ctle_error_dB','objective_valid','four_level_valid','four_occupancy_min','separation','within_cluster_noise'});
    assert(all(ctle.residual_ctle_error_dB<=0.2+1e-12),'CTLE residual exceeds limit');
    adapt=readtable(fullfile(root,'adaptation_state_trace.csv')); requireVars(adapt,{'state','objective','disturbed_objective',...
        'recovered_objective','control_changed','ctle_requested_dB','ctle_target_dB','ctle_applied_dB','ctle_residual_dB',...
        'rx_term_gain_applied','tx_gain_residual','dll_phase_initial_UI',...
        'dll_phase_applied_UI','dll_phase_residual_UI','dcc_duty_initial_UI','dcc_duty_applied_UI','dcc_duty_residual_UI',...
        'sampler_offset_initial_codes','sampler_offset_applied_codes','sampler_offset_residual_codes','ctle_initial_error_dB','ctle_residual_dB',...
        'four_level_valid','four_occupancy_min','logical_eye_margin','leveling_scale'});
    assert(all(~(adapt.objective>0 & ~adapt.four_level_valid)),'adaptation objective accepted invalid PAM4 levels');
    states=string(adapt.state); assert(isequal(states,["RESET";"STARTUP_IMPEDANCE_CAL";"CLOCK_CAL";"INITIAL_EQ_TRAIN";"MISSION_TRACK"]),...
        'adaptation states invalid'); mission=adapt(states=="MISSION_TRACK",:);
    assert(all(isfinite(adapt.ctle_requested_dB)&isfinite(adapt.ctle_target_dB)&isfinite(adapt.ctle_applied_dB)&...
        isfinite(adapt.ctle_residual_dB))&&all(abs(adapt.ctle_residual_dB-abs(adapt.ctle_applied_dB-adapt.ctle_target_dB))<=1e-12),...
        'CTLE state residual formula invalid');
    assert(any(abs(adapt.ctle_requested_dB-4.13)<1e-12&abs(adapt.ctle_applied_dB-4.2)<1e-12&...
        abs(adapt.ctle_residual_dB-0.07)<1e-12),'off-grid CTLE state evidence missing');
    assert(all(adapt.ctle_residual_dB<=cfg.model.adaptation.residualLimit.ctle_dB+1e-12),'CTLE state residual limit failed');
    assert(mission.disturbed_objective<mission.recovered_objective&&mission.control_changed,'adaptation did not recover');
    assert(mission.dll_phase_residual_UI<=cfg.model.adaptation.residualLimit.dllPhaseUI+1e-12&&...
        mission.dcc_duty_residual_UI<=cfg.model.adaptation.residualLimit.dccDutyUI+1e-12&&...
        mission.sampler_offset_residual_codes<=cfg.model.adaptation.residualLimit.samplerOffsetCodes+1e-12&&...
        mission.ctle_residual_dB<=cfg.model.adaptation.residualLimit.ctle_dB+1e-12,'adaptation residual limit failed');
    comparison=readtable(fullfile(root,'paper_comparison.csv')); requireVars(comparison,{'category','item','paper_value','model_value'});
    manifest=jsondecode(fileread(fullfile(root,'legacy_t1_t9','manifest.json'))); probes=jsondecode(fileread(fullfile(root,'legacy_t1_t9','probes.json'))); %#ok<NASGU>
    baselineMat=load(fullfile(root,'baseline_probes.mat')); assert(isfield(baselineMat,'probes')&&isfield(baselineMat,'probeManifest'),...
        'baseline MAT missing probes/probeManifest');
    for name={'txPad','channelOut','ctleOut','slicerIn','rxBits'}, assert(isfield(baselineMat.probes,name{1})&&~isempty(baselineMat.probes.(name{1})),...
            'baseline MAT missing core probe %s',name{1}); end
    for name={'rawCentroids','logicalCentroids','occupancy','levelingScale','fitResidual','fitResidualTolerance','finiteFraction','levelsValid','pam4Mapping','logicalOuterLevel'}, assert(isfield(baselineMat.probes,name{1}),...
            'baseline MAT missing leveling/contract field %s',name{1}); end
    assert(baselineMat.probes.levelsValid&&isequal(baselineMat.probes.pam4Mapping,'gray_00_01_11_10')&&...
        baselineMat.probes.logicalOuterLevel==3&&all(isfinite(baselineMat.probes.rawCentroids))&&all(isfinite(baselineMat.probes.logicalCentroids))&&...
        isfinite(baselineMat.probes.fitResidual)&&baselineMat.probes.fitResidual<=baselineMat.probes.fitResidualTolerance&&baselineMat.probes.finiteFraction==1,...
        'baseline leveling metadata invalid');
    for name={'txPad','channelOut','ctleOut','slicerIn','rxBits'}, assert(isfield(baselineMat.probeManifest,name{1}),...
            'baseline MAT missing manifest field %s',name{1}); end
    legacyMat=load(fullfile(root,'legacy_t1_t9','regression.mat'));
    for name={'summary','T1','T3','T6','T7','T9','behavior','best'}, assert(isfield(legacyMat,name{1})&&~isempty(legacyMat.(name{1})),...
            'legacy MAT missing %s',name{1}); end
    assert(isstruct(legacyMat.behavior)&&all(isfield(legacyMat.behavior,{'loss','ctle','cdr'}))&&...
        isstruct(legacyMat.best)&&isfield(legacyMat.best,'ber'),'legacy MAT structure fields invalid');
    assert(strlength(string(fileread(fullfile(root,'assumptions.md'))))>0&&strlength(string(fileread(fullfile(root,'paper_comparison.md'))))>0);
    summary=readcell(fullfile(root,'regression_summary.csv'),'Delimiter',','); assert(size(summary,2)>=3&&strcmp(summary{1,1},'stage')&&strcmp(summary{1,2},'pass'),...
        'regression summary schema invalid'); if requireSummary, assert(all(cell2mat(summary(2:end,2))==1),'regression summary contains failure'); end
    legacy=readcell(fullfile(root,'legacy_t1_t9','summary.csv'),'Delimiter',','); assert(size(legacy,2)>=2&&strcmp(legacy{1,1},'test')&&strcmp(legacy{1,2},'pass')&&size(legacy,1)==10&&all(cell2mat(legacy(2:end,2))==1),...
        'legacy T1-T9 evidence invalid');
    t1=readtable(fullfile(root,'legacy_t1_t9','T1_eye_metrics.csv')); requireVars(t1,{'modeIndex','baudG','lossDb','ber','eyeHeight'}); expectedT1=[repelem((1:4)',4) repmat([28;28;28;28;56;56;56;56],2,1) repmat([0;4;8;10],4,1)]; actualT1=sortrows(t1,{'modeIndex','baudG','lossDb'}); assert(height(t1)==16&&isequal(actualT1{:,1:3},expectedT1)&&all(t1.ber>=0&t1.ber<=1)&&all(isfinite(t1.eyeHeight)),'legacy T1 schema/value invalid');
    t3=readtable(fullfile(root,'legacy_t1_t9','T3_bathtub.csv')); requireVars(t3,{'offsetUI','phase','delay','phaseBer'}); center=find(abs(t3.offsetUI)<1e-12,1); assert(all(t3.phaseBer>=0&t3.phaseBer<=1)&&all(isfinite(t3.phaseBer))&&~isempty(center)&&t3.phaseBer(center)<=t3.phaseBer(1)&&t3.phaseBer(center)<=t3.phaseBer(end),'legacy T3 schema/value invalid');
    t6=readtable(fullfile(root,'legacy_t1_t9','T6_patterns.csv')); requireVars(t6,{'patternIndex','injected','detected'}); expectedT6=sortrows([repelem((1:4)',2) repmat([0;17],4,1)]); actualT6=sortrows(t6{:,1:2}); assert(isequal(actualT6,expectedT6)&&all(t6.injected==t6.detected),'legacy T6 mismatch');
    t7=readtable(fullfile(root,'legacy_t1_t9','T7_modulation.csv')); requireVars(t7,{'modulation','ber'}); assert(isequal(sort(string(t7.modulation)),sort(["NRZ";"PAM4"]))&&all(t7.ber>=0&t7.ber<=1)&&t7.ber(strcmp(string(t7.modulation),'PAM4'))>t7.ber(strcmp(string(t7.modulation),'NRZ')),'legacy T7 schema/value invalid');
    t9=readtable(fullfile(root,'legacy_t1_t9','T9_loopback.csv')); requireVars(t9,{'mode','pass'}); assert(isequal(sort(string(t9.mode)),sort(["shallow";"serial_lane";"die_to_die"]))&&height(t9)==3&&all(t9.pass),'legacy T9 failed');
    junit=fileread(fullfile(root,'legacy_t1_t9','junit.xml')); assert(contains(junit,'tests="9"')&&contains(junit,'failures="0"')&&count(junit,'<testcase')==9,'legacy JUnit invalid');
    assert(strlength(string(fileread(fullfile(root,'assumptions.md'))))>0&&~isempty(imfinfo(fullfile(root,'plots','cdr_residual_phase.png'))));
    ok=true; detail='OK';
catch ME
    detail=ME.message;
end
end

function requireVars(t,names)
for k=1:numel(names), assert(ismember(names{k},t.Properties.VariableNames),'Missing column: %s',names{k}); end
end

function checkBer(t,names,context)
requireVars(t,[names context]); assert(all(t.errors>=0)&&all(t.measured_bits>0),'invalid BER counts');
assert(all(t.errors<=t.measured_bits),'errors exceed measured bits');
assert(all(t.empirical_BER>=0&t.empirical_BER<=1)&&all(abs(t.empirical_BER-t.errors./t.measured_bits)<=1e-12),...
    'empirical BER ratio invalid');
assert(all(t.ber_upper_95>=t.empirical_BER-1e-12)&all(t.ber_upper_95<=1+1e-12),...
    'invalid BER/upper-bound values'); z=t.errors==0; if any(z), assert(all(abs(t.ber_upper_95(z)-3./t.measured_bits(z))<1e-12),'zero-error bound invalid'); end
assert(all(isfinite(t.seed)),'invalid seed context'); assert(all(isfinite(t.rate_context_Gbps)&t.rate_context_Gbps>0),'invalid rate context');
assert(all(isfinite(t.line_rate_Gbps)&t.line_rate_Gbps>0),'invalid line-rate context');
assert(all(strlength(string(t.mode))>0&strlength(string(t.lane_context))>0),'invalid mode/lane context');
assert(all(isfinite(t.sample_bits)&t.sample_bits>0),'invalid sample context');
end
